    BlA64 = (ord(BlTagId), "bl")  ## branch with link (function call)
    BeqA64 = (ord(BeqTagId), "beq")  ## branch if equal
    BneA64 = (ord(BneTagId), "bne")  ## branch if not equal
    BltA64 = (ord(BltTagId), "blt")  ## branch if less than (signed)
