    CsetneA64 = (ord(CsetneTagId), "csetne")  ## conditional set: D = if not equal then 1 else 0
    CsetltA64 = (ord(CsetltTagId), "csetlt")  ## conditional set: D = if less than (signed) then 1 else 0
    CsetleA64 = (ord(CsetleTagId), "csetle")  ## conditional set: D = if less or equal (signed) then 1 else 0
    CsetgtA64 = (ord(CsetgtTagId), "csetgt")  ## conditional set: D = if greater than (signed) then 1 else 0
    CsetgeA64 = (ord(CsetgeTagId), "csetge")  ## conditional set: D = if greater or equal (signed) then 1 else 0
    CsetloA64 = (ord(CsetloTagId), "csetlo")  ## conditional set: D = if lower (unsigned <) then 1 else 0
    CsetlsA64 = (ord(CsetlsTagId), "csetls")  ## conditional set: D = if lower or same (unsigned <=) then 1 else 0
    CsethiA64 = (ord(CsethiTagId), "csethi")  ## conditional set: D = if higher (unsigned >) then 1 else 0
    CsethsA64 = (ord(CsethsTagId), "cseths")  ## conditional set: D = if higher or same (unsigned >=) then 1 else 0
    LdaxrA64 = (ord(LdaxrTagId), "ldaxr")  ## load-acquire exclusive register
    StlxrA64 = (ord(StlxrTagId), "stlxr")  ## store-release exclusive register (St = status)
    LdarA64 = (ord(LdarTagId), "ldar")  ## load-acquire register
    StlrA64 = (ord(StlrTagId), "stlr")  ## store-release register
    FcvtA64 = (ord(FcvtTagId), "fcvt")  ## fp precision convert (f32<->f64)
    FstpA64 = (ord(FstpTagId), "fstp")  ## fp store pair (pre-indexed)
    FldpA64 = (ord(FldpTagId), "fldp")  ## fp load pair (post-indexed)
    FldrqA64 = (ord(FldrqTagId), "fldrq")  ## load a 128-bit q register from memory (`ldr Qt, [Xn, #imm]`, imm a multiple of 16). `D` is spelled as the register's d/s tag — the q width is the instruction's, exactly as `movdqu`'s 16-byte access is on x64
    FstrqA64 = (ord(FstrqTagId), "fstrq")  ## store a 128-bit q register: `(fstrq <mem> <fpreg>)`, operand order as `fstr`
    VfaddA64 = (ord(VfaddTagId), "vfadd")  ## vector fp add, lane-wise (D = A + B): arrangement `.2d` when the registers are d-spelled, `.4s` when s-spelled
    VfsubA64 = (ord(VfsubTagId), "vfsub")  ## vector fp subtract, lane-wise (D = A - B), arrangement as `vfadd`
    VfmulA64 = (ord(VfmulTagId), "vfmul")  ## vector fp multiply, lane-wise (D = A * B), arrangement as `vfadd`
    VfmlaA64 = (ord(VfmlaTagId), "vfmla")  ## vector fp fused multiply-add, lane-wise (D = D + A * B), arrangement as `vfadd`
